 const string Mud="Assets/3D Haven/Path Painter II/Editor/Demo/Terrains/DocsTerrain/TerrainLayers/stdMudRocky.terrainlayer",Grass="Assets/PinwheelStudio/Vista/Personal/Samples/TerrainLayers/Grass Light/Grass_Light_VistaSample.terrainlayer",Sand="Assets/PinwheelStudio/Vista/Personal/Samples/TerrainLayers/Sand/Sand_VistaSample.terrainlayer";
 public static void UpgradeBoth(){foreach(var path in new[]{KeepawayAuthoring.Scene,KeepawayChaosAuthoring.CabScene}){EditorSceneManager.OpenScene(path);Install(UnityEngine.Object.FindAnyObjectByType<KeepawayMatch>());EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene());}AssetDatabase.SaveAssets();}
 public static void Install(KeepawayMatch m){if(m.chaosField!=null&&m.chaosField.arenaRepairVersion>=1){Debug.Log("Preserved expanded authored Keepaway models and surfaces.");return;}var old=GameObject.Find(Root);if(old!=null)UnityEngine.Object.DestroyImmediate(old);var root=new GameObject(Root);var ground=m.chaosField.ground;if(ground==null)ground=m.chaosField.gameObject.AddComponent<KeepawayGround>();m.chaosField.ground=ground;ground.themes=new[]{Layer("Rocky mud terrain",Mud,.32f),Snow(),Layer("Beach sand terrain",Sand,.09f),Layer("Meadow terrain",Grass,.12f)};
 var surface=GameObject.Find("Rounded arena surface");var mesh=GroundMesh();surface.GetComponent<MeshFilter>().sharedMesh=Save(mesh,"Contoured textured arena.asset");ground.surface=surface.GetComponent<MeshRenderer>();var shape=surface.GetComponent<MeshCollider>();if(shape==null)shape=surface.AddComponent<MeshCollider>();shape.sharedMesh=surface.GetComponent<MeshFilter>().sharedMesh;shape.sharedMaterial=GameObject.Find("Keepaway arena").GetComponent<Collider>().sharedMaterial;GameObject.Find("Keepaway arena").GetComponent<Collider>().enabled=false;
 for(int i=0;i<m.chaosField.solidProps.Length;i++){var t=m.chaosField.solidProps[i];RemoveVisuals(t);var holder=Holder(t);string path=i%3==0?"Assets/ConstructionPropsBundle/URP/Prefabs/SM_Barrel01 Variant.prefab":i%3==1?"Assets/RoadPropsPack/URP/Prefabs/WoodBox_URP.prefab":"Assets/IndieKit/Crates and Barrels/Prefabs/Non-Destructible/crate_01.prefab";if(i%3==0){for(int b=0;b<4;b++){var barrel=new GameObject("Barrel cluster "+b).transform;barrel.SetParent(holder,false);barrel.localPosition=new Vector3(b%2==0?-.7f:.7f,0,b<2?-.6f:.6f);Fit(barrel,path,new Vector3(1.2f,1.2f,1.2f),-.6f);}}else Fit(holder,path,new Vector3(2.9f,1.2f,2.4f),-.6f,true);}
 for(int i=0;i<m.chaosField.movable.Length;i++){var t=m.chaosField.movable[i].transform;RemoveVisuals(t);Fit(Holder(t),"Assets/RoadPropsPack/URP/Prefabs/TireStacked01_URP.prefab",new Vector3(1.5f,1.4f,1.5f),-.7f,true);}
 var rampPrefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/TruckTerrierRacing/Prefabs/Timber launch ramp.prefab");if(rampPrefab==null)throw new Exception("Modeled timber ramp missing");for(int i=0;i<m.chaosField.ramps.Length;i++){var prior=m.chaosField.ramps[i];var g=(GameObject)PrefabUtility.InstantiatePrefab(rampPrefab);PrefabUtility.UnpackPrefabInstance(g,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);g.name="Modeled timber escape ramp "+i;foreach(var renderer in g.GetComponentsInChildren<MeshRenderer>()){var mats=renderer.sharedMaterials;for(int a=0;a<mats.Length;a++)if(mats[a]!=null&&mats[a].name=="M_RacksProps"){const string woodPath="Assets/TruckKeepaway/Materials/Rough construction timber.mat";var wood=AssetDatabase.LoadAssetAtPath<Material>(woodPath);if(wood==null){wood=new Material(mats[a]);wood.SetFloat("_Smoothness",.16f);wood.SetFloat("_BumpScale",.45f);AssetDatabase.CreateAsset(wood,woodPath);}mats[a]=wood;}renderer.sharedMaterials=mats;}g.transform.position=new Vector3(i%2==0?-19:19,0,i<2?0:13);g.transform.rotation=Quaternion.Euler(0,(i<2?0:90)+(i%2==0?0:180),0);g.transform.localScale=new Vector3(5f/8,.9f/1.04f,1);g.GetComponent<MeshCollider>().convex=true;foreach(var behaviour in g.GetComponentsInChildren<MonoBehaviour>(true))UnityEngine.Object.DestroyImmediate(behaviour);UnityEngine.Object.DestroyImmediate(prior.gameObject);m.chaosField.ramps[i]=g.transform;}
 for(int i=0;i<m.chaosField.sweepers.Length;i++){var t=m.chaosField.sweepers[i].transform;RemoveVisuals(t);var holder=Holder(t);for(int j=0;j<3;j++){var segment=new GameObject("Striped steel barrier segment").transform;segment.SetParent(holder,false);segment.localPosition=new Vector3((j-1)*1.98f,0,0);Fit(segment,"Assets/RoadPropsPack/URP/Prefabs/RoadBlock02_URP.prefab",new Vector3(1.98f,.45f,.55f),-.225f,true);} }
 for(int i=0;i<m.chaosField.patches.Length;i++){var t=m.chaosField.patches[i];t.GetComponent<Renderer>().enabled=false;foreach(Transform child in t.Cast<Transform>().ToArray())UnityEngine.Object.DestroyImmediate(child.gameObject);var patch=new GameObject("Irregular textured traction patch");patch.transform.SetParent(root.transform,false);patch.transform.position=new Vector3(t.position.x,0,t.position.z);patch.AddComponent<MeshFilter>().sharedMesh=Save(Patch(t.position,i),"Organic traction patch "+i+".asset");patch.AddComponent<MeshRenderer>().sharedMaterial=i%2==0?ground.themes[0]:Puddle();}
 ground.dressing=new GameObject[4];for(int theme=0;theme<4;theme++){var group=new GameObject("Biome scenery "+theme);group.transform.SetParent(root.transform,false);ground.dressing[theme]=group;for(int i=0;i<12;i++){var anchor=new GameObject("Installed perimeter scenery "+i).transform;anchor.SetParent(group.transform,false);float x=(i%6-2.5f)*11.5f,z=i<6?-23:23;anchor.localPosition=new Vector3(x,0,z);anchor.localRotation=Quaternion.Euler(0,i*137,0);string path=theme==2&&i%3==0?"Assets/PinwheelStudio/Vista/Personal/Samples/Prefabs/VistaSample_PalmTree.prefab":theme==3&&i%2==0?"Assets/JC_LP_MegaCity/Prefabs/Nature/SM_Nature_Grass_01.prefab":"Assets/Toon Gas Station/Prefabs/Rock_Cluster_1A.prefab";Fit(anchor,path,new Vector3(4,theme==2&&i%3==0?6:1.8f,4),0);}}
 ground.Select(m.chaosField.seed);m.obstacles=m.chaosField.solidProps.Select(t=>t.GetComponent<Collider>()).Concat(m.chaosField.ramps.Select(t=>t.GetComponent<Collider>())).Concat(m.chaosField.sweepers.Select(t=>t.GetComponent<Collider>())).ToArray();m.broadcast.Pose(new Vector3(0,1,0),new Vector3(0,35,-26),60,true);m.broadcast.GetComponent<LWS.TruckSports.SportsCameraFit>().Apply();EditorUtility.SetDirty(m.chaosField);EditorUtility.SetDirty(m);KeepawayRegressionAuthoring.Install(m);KeepawayHudAuthoring.Install(m);Debug.Log("KEEP_PRESENTATION_SAVED four textured biomes, actual contour collision, installed models");}
 static Transform Holder(Transform t){var holder=new GameObject("Installed model presentation").transform;holder.SetParent(t,false);holder.localScale=new Vector3(1/t.localScale.x,1/t.localScale.y,1/t.localScale.z);return holder;}
 static void RemoveVisuals(Transform t){foreach(Transform child in t.Cast<Transform>().ToArray())UnityEngine.Object.DestroyImmediate(child.gameObject);var renderer=t.GetComponent<Renderer>();if(renderer!=null)renderer.enabled=false;}
 // Normalize before parenting: world-space scene position must never enter a model's local offset.
 public static void Fit(Transform parent,string path,Vector3 size,float bottom,bool stretch=false,string materialFolder="TruckKeepaway"){var source=AssetDatabase.LoadAssetAtPath<GameObject>(path);if(source==null)throw new Exception("Installed model absent: "+path);var g=UnityEngine.Object.Instantiate(source);g.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);foreach(var j in g.GetComponentsInChildren<Joint>(true))UnityEngine.Object.DestroyImmediate(j);foreach(var b in g.GetComponentsInChildren<MonoBehaviour>(true))UnityEngine.Object.DestroyImmediate(b);foreach(var c in g.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(c);foreach(var b in g.GetComponentsInChildren<Rigidbody>(true))UnityEngine.Object.DestroyImmediate(b);var renderers=g.GetComponentsInChildren<Renderer>(true);var bounds=renderers[0].bounds;foreach(var r in renderers)bounds.Encapsulate(r.bounds);float scale=Mathf.Min(size.x/bounds.size.x,size.y/bounds.size.y,size.z/bounds.size.z);var factor=stretch?new Vector3(size.x/bounds.size.x,size.y/bounds.size.y,size.z/bounds.size.z):Vector3.one*scale;g.transform.localScale=Vector3.Scale(g.transform.localScale,factor);g.transform.position=-Vector3.Scale(new Vector3(bounds.center.x,bounds.min.y,bounds.center.z),factor)+Vector3.up*bottom;g.transform.SetParent(parent,false);g.name="Installed "+source.name;foreach(var r in renderers){r.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.On;r.receiveShadows=true;var mats=r.sharedMaterials;for(int i=0;i<mats.Length;i++)if(mats[i]!=null&&!mats[i].shader.name.Contains("Universal")&&!mats[i].shader.name.Contains("URP")){string matPath="Assets/"+materialFolder+"/Materials/Imported "+mats[i].name+".mat";var owned=AssetDatabase.LoadAssetAtPath<Material>(matPath);if(owned==null){owned=new Material(Shader.Find("Universal Render Pipeline/Lit"));if(mats[i].HasProperty("_Color"))owned.color=mats[i].color;owned.mainTexture=mats[i].mainTexture;AssetDatabase.CreateAsset(owned,matPath);}mats[i]=owned;}r.sharedMaterials=mats;}}
 static Material Layer(string name,string path,float gloss){var layer=AssetDatabase.LoadAssetAtPath<TerrainLayer>(path);if(layer==null||layer.diffuseTexture==null)throw new Exception("Installed terrain layer missing: "+path);var m=SportsEventAuthoring.Mat(Folder,name,Color.white,gloss);m.mainTexture=layer.diffuseTexture;m.SetTexture("_BumpMap",layer.normalMapTexture);m.color=name.StartsWith("Beach")?new Color(.82f,.65f,.40f):name.StartsWith("Meadow")?new Color(.52f,.68f,.37f):new Color(.72f,.65f,.56f);m.SetFloat("_BumpScale",.65f);m.EnableKeyword("_NORMALMAP");m.mainTextureScale=Vector2.one*2/layer.tileSize.x;return m;}
 static Material Snow(){var m=SportsEventAuthoring.Mat(Folder,"Snowfield terrain",new Color(.86f,.93f,1),.22f);m.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/WeatherMaker/Prefab/Textures/Precipitation/WeatherMakerSnowSeamless1.jpg");m.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/NOT_Lonely/Weatherade SRS/Samples/SharedContent/Materials/Terrain_snow_NormalLOD.png"));m.SetFloat("_BumpScale",.7f);m.EnableKeyword("_NORMALMAP");return m;}
 static Material Puddle(){var m=SportsEventAuthoring.Mat(Folder,"Textured wet earth",new Color(.22f,.19f,.15f),.48f);var layer=AssetDatabase.LoadAssetAtPath<TerrainLayer>(Mud);m.mainTexture=layer.diffuseTexture;m.SetTexture("_BumpMap",layer.normalMapTexture);m.EnableKeyword("_NORMALMAP");m.SetFloat("_BumpScale",.35f);return m;}
 static Mesh GroundMesh(){const int nx=129,nz=73;var vertices=new Vector3[nx*nz];var uv=new Vector2[vertices.Length];var tris=new List<int>();for(int z=0;z<nz;z++){float pz=Mathf.Lerp(-18.04f,18.04f,z/(float)(nz-1));float dz=Mathf.Max(0,Mathf.Abs(pz)-11);float half=25+Mathf.Sqrt(Mathf.Max(0,7.04f*7.04f-dz*dz));for(int x=0;x<nx;x++){float px=Mathf.Lerp(-half,half,x/(float)(nx-1));int k=z*nx+x;vertices[k]=new Vector3(px,KeepawayGround.Height(px,pz),pz);uv[k]=new Vector2(px,pz)*.5f;if(x<nx-1&&z<nz-1)tris.AddRange(new[]{k,k+nx,k+1,k+1,k+nx,k+nx+1});}}var m=new Mesh{name="Gently contoured rounded play surface"};m.vertices=vertices;m.uv=uv;m.SetTriangles(tris,0);m.RecalculateNormals();m.RecalculateTangents();m.RecalculateBounds();return m;}
 static Mesh Patch(Vector3 center,int seed){const int rings=10,segments=48;var p=new List<Vector3>{new Vector3(0,KeepawayGround.Height(center.x,center.z)+.035f,0)};var uv=new List<Vector2>{Vector2.zero};var tris=new List<int>();for(int ring=1;ring<=rings;ring++)for(int i=0;i<segments;i++){float a=i*Mathf.PI*2/segments,r=(.88f+.10f*Mathf.PerlinNoise(seed*3+i*.3f,13))*ring/rings;float x=Mathf.Cos(a)*3*r,z=Mathf.Sin(a)*2.5f*r;p.Add(new Vector3(x,KeepawayGround.Height(center.x+x,center.z+z)+.035f,z));uv.Add(new Vector2(x,z)*.5f);int k=1+(ring-1)*segments+i,n=1+(ring-1)*segments+(i+1)%segments;if(ring==1)tris.AddRange(new[]{0,n,k});else{int prev=k-segments,pn=n-segments;tris.AddRange(new[]{prev,pn,k,k,pn,n});}}var m=new Mesh{name="Organic mud and wet-ground patch"};m.SetVertices(p);m.SetUVs(0,uv);m.SetTriangles(tris,0);m.RecalculateNormals();m.RecalculateTangents();m.RecalculateBounds();return m;}
 static Mesh Save(Mesh mesh,string name){string path="Assets/TruckKeepaway/Materials/"+name;var asset=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(asset==null){AssetDatabase.CreateAsset(mesh,path);return mesh;}EditorUtility.CopySerialized(mesh,asset);UnityEngine.Object.DestroyImmediate(mesh);EditorUtility.SetDirty(asset);return asset;}
 public static void Validate(){foreach(var path in new[]{KeepawayAuthoring.Scene,KeepawayChaosAuthoring.CabScene}){EditorSceneManager.OpenScene(path);var m=UnityEngine.Object.FindAnyObjectByType<KeepawayMatch>();var g=m.chaosField.ground;if(g==null||g.themes.Length!=4||g.themes.Any(x=>x==null||x.mainTexture==null)||g.surface.GetComponent<MeshCollider>()==null||g.surface.GetComponent<MeshFilter>().sharedMesh.uv.Length<9000)throw new Exception("Keepaway ground assets invalid");var observed=new HashSet<int>();for(int i=0;i<100;i++){g.Select(i);observed.Add(g.Theme);}if(observed.Count!=4)throw new Exception("All four seeded ground themes must be reachable");foreach(var prop in m.chaosField.solidProps){var renders=prop.GetComponentsInChildren<Renderer>().Where(r=>r.enabled).ToArray();if(renders.Length==0)throw new Exception("Missing installed prop model");var bounds=renders[0].bounds;foreach(var r in renders)bounds.Encapsulate(r.bounds);if(Vector2.Distance(new Vector2(bounds.center.x,bounds.center.z),new Vector2(prop.position.x,prop.position.z))>.1f||bounds.size.y<.6f)throw new Exception("Prop art must be centered over its collider: "+prop.name);}KeepawayRegressionAuthoring.Validate();Debug.Log("KEEP_PRESENTATION_VALIDATED "+path);}}
